const resolveObjection = `-- name: ResolveObjection :execrows
UPDATE objections SET resolved_at = ?, resolution = ? WHERE id = ? AND resolved_at IS NULL
`

type ResolveObjectionParams struct {
	ResolvedAt sql.NullTime
	Resolution string
	ID         int64
}

func (q *Queries) ResolveObjection(ctx context.Context, arg ResolveObjectionParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, resolveObjection, arg.ResolvedAt, arg.Resolution, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

